import{_ as e}from"./chunks/image6.CP232qgI.js";import{_ as i}from"./chunks/image2.DLIlWW7l.js";import{_ as a,o as r,c as n,ah as s}from"./chunks/framework.DE1cwP7O.js";const l="/projects/DaDablock-AI/en/starter-kit/assets/image1.DuK3Zkn_.png",o="/projects/DaDablock-AI/en/starter-kit/assets/image2.BZ2jeGDl.png",c="/projects/DaDablock-AI/en/starter-kit/assets/image1.BNtR0Z_1.png",g="/projects/DaDablock-AI/en/starter-kit/assets/image2.DADdVOwo.png",d="/projects/DaDablock-AI/en/starter-kit/assets/image3.B1yA9wQb.png",h="/projects/DaDablock-AI/en/starter-kit/assets/image4.BLLC_Qf_.png",m="/projects/DaDablock-AI/en/starter-kit/assets/image5.vHiDdOHp.png",p="/projects/DaDablock-AI/en/starter-kit/assets/image6.BuR8OT3H.png",u="/projects/DaDablock-AI/en/starter-kit/assets/image7.D4sdZDs1.png",w="/projects/DaDablock-AI/en/starter-kit/assets/image8.BruHqUJr.png",b="/projects/DaDablock-AI/en/starter-kit/assets/image1.C8y-uHVE.png",f="/projects/DaDablock-AI/en/starter-kit/assets/image2.4k55HlQu.png",_="/projects/DaDablock-AI/en/starter-kit/assets/image3.BAKQvAyJ.png",k="/projects/DaDablock-AI/en/starter-kit/assets/image4.51XFnSxc.png",v="/projects/DaDablock-AI/en/starter-kit/assets/image5.CiCa4cB-.png",y="/projects/DaDablock-AI/en/starter-kit/assets/image1.Cyh4aVyI.png",D="/projects/DaDablock-AI/en/starter-kit/assets/image7.D0ZOkcgu.png",x="/projects/DaDablock-AI/en/starter-kit/assets/image8._mWneemC.png",I="/projects/DaDablock-AI/en/starter-kit/assets/image10.4MUrcIBb.png",A="/projects/DaDablock-AI/en/starter-kit/assets/image1.ye3jEIXI.png",P="/projects/DaDablock-AI/en/starter-kit/assets/image1.BHx1buEe.png",q="/projects/DaDablock-AI/en/starter-kit/assets/image2.nrgtvAk7.png",j="/projects/DaDablock-AI/en/starter-kit/assets/image3.C9izSCCo.png",C="/projects/DaDablock-AI/en/starter-kit/assets/image4.CS4ktiZb.png",S="/projects/DaDablock-AI/en/starter-kit/assets/image6.sjIyBD9M.png",z="/projects/DaDablock-AI/en/starter-kit/assets/image1.xOQkFzOy.png",T="/projects/DaDablock-AI/en/starter-kit/assets/image2.DuyMPDw2.png",O="/projects/DaDablock-AI/en/starter-kit/assets/image3.iTwzmnhz.png",B="/projects/DaDablock-AI/en/starter-kit/assets/image4.DRkInU8K.png",L="/projects/DaDablock-AI/en/starter-kit/assets/image1.gAgmRPNY.png",E="/projects/DaDablock-AI/en/starter-kit/assets/image2.B8zc0Jpr.png",M="/projects/DaDablock-AI/en/starter-kit/assets/image3.Bfu-hF-7.png",R="/projects/DaDablock-AI/en/starter-kit/assets/image4.Dpw6DOJM.png",H="/projects/DaDablock-AI/en/starter-kit/assets/image5.B8U9f3P-.png",N="/projects/DaDablock-AI/en/starter-kit/assets/image6.B3MpXkrF.png",U="/projects/DaDablock-AI/en/starter-kit/assets/image7.Co4TRYvD.png",W="/projects/DaDablock-AI/en/starter-kit/assets/image1.Hb_dPJWr.png",F="/projects/DaDablock-AI/en/starter-kit/assets/image2.DUscFuCm.png",Q="/projects/DaDablock-AI/en/starter-kit/assets/image3.BMtDhVDd.png",X="/projects/DaDablock-AI/en/starter-kit/assets/image4.BBu3HQsu.png",J="/projects/DaDablock-AI/en/starter-kit/assets/image5.DL3pFkf4.png",V="/projects/DaDablock-AI/en/starter-kit/assets/image7.BJ7LQ1S2.png",G="/projects/DaDablock-AI/en/starter-kit/assets/image1.C3rbkadd.png",K="/projects/DaDablock-AI/en/starter-kit/assets/image3.DaearKL0.png",st=JSON.parse('{"title":"2. Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Quick_Start.md","filePath":"docs/2_Quick_Start.md"}'),Z={name:"docs/2_Quick_Start.md"};function $(Y,t,tt,et,ot,it){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_2-quick-start" tabindex="-1">2. Quick Start <a class="header-anchor" href="#_2-quick-start" aria-label="Permalink to &quot;2. Quick Start&quot;">​</a></h1><p id="anther2.1"></p><h2 id="_2-1-large-language-model-interaction" tabindex="-1">2.1 Large Language Model Interaction <a class="header-anchor" href="#_2-1-large-language-model-interaction" aria-label="Permalink to &quot;2.1 Large Language Model Interaction&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This section introduces the WonderLLM module for a quick start. Since there are various ways to play with this module, refer to <a href="https://wiki.hiwonder.com/projects/DaDablock-AI/en/starter-kit/docs/4_Software_and_Hardware_Guide.html#wonderllm-module" target="_blank" rel="noreferrer">Section 4.4 WonderLLM Module</a> for detailed learning.</strong></p></div><h3 id="_2-1-1-powering-on-the-device" tabindex="-1">2.1.1 Powering On the Device <a class="header-anchor" href="#_2-1-1-powering-on-the-device" aria-label="Permalink to &quot;2.1.1 Powering On the Device&quot;">​</a></h3><ul><li>The module supports the following ports for power supply: <strong>① Upper Type-C port</strong>, <strong>② Lower Type-C port</strong>, and <strong>③ 4-PIN I2C communication interface</strong>. Connect an external power supply to any of these ports to automatically power on the module.</li></ul><div align="center"><img loading="lazy" height="672" width="704" src="'+l+'" class="common_img" style="width:300px;"></div><ul><li>After powering on the module, the screen displays the <strong>Wi-Fi name</strong> and the <strong>web configuration URL</strong>, accompanied by a voice broadcast. Complete the network configuration for the module before starting the following sections.</li></ul><div align="center"><img loading="lazy" height="1973" width="1679" src="'+o+'" class="common_img" style="width:300px;"></div><p id="anther2.1.2"></p><h3 id="_2-1-2-module-network-configuration" tabindex="-1">2.1.2 Module Network Configuration <a class="header-anchor" href="#_2-1-2-module-network-configuration" aria-label="Permalink to &quot;2.1.2 Module Network Configuration&quot;">​</a></h3><p>After powering on, the module starts the network connection process. The screen displays the <strong>device hotspot name</strong> and the <strong>access URL</strong>, accompanied by a voice broadcast. The AI module will enable its own hotspot for connection and configuration. Hotspot names vary by device, following the format <strong>Robot-xxxx</strong>. This section uses the hotspot <strong>Robot-B7B9</strong> as an example.</p><div align="center"><img loading="lazy" height="1973" width="1679" src="'+o+'" class="common_img" style="width:300px;"></div><ol><li>Search for and connect to the corresponding hotspot using a computer or smartphone. Note that this hotspot does not require a password.</li></ol><div align="center"><img loading="lazy" height="186" width="359" src="'+c+'" class="common_img" style="width:400px;"></div><div align="center"><img loading="lazy" height="139" width="359" src="'+g+'" class="common_img" style="width:400px;"></div><ol start="2"><li>Open any browser and go to the following URL: <a href="http://192.168.4.1" target="_blank" rel="noreferrer">http://192.168.4.1</a>. Alternatively, click the <a href="http://192.168.4.1/" target="_blank" rel="noreferrer"><u>Network Configuration</u></a> hyperlink for direct access.</li></ol><div align="center"><img loading="lazy" height="546" width="1185" src="'+d+'" class="common_img" style="width:500px;"></div><ol start="3"><li>Enter the name of the hotspot to which the module should automatically connect upon power-on in field ①, and enter the hotspot password in field ②. Finally, click <strong>Connect</strong> in field ③. The module will attempt to search for and connect to a matching hotspot in the current environment using the provided network credentials.</li></ol><div align="center"><img loading="lazy" height="244" width="1165" src="'+h+'" class="common_img" style="width:900px;"></div><ol start="4"><li>The interface displays a list of available hotspots in the current environment scanned by the module. Click an item to automatically populate field ① with the corresponding hotspot name for a faster and more convenient setup.</li></ol><div align="center"><img loading="lazy" height="224" width="375" src="'+m+'" class="common_img" style="width:500px;"></div><ol start="5"><li>If the following prompt appears on the interface, it indicates that the hotspot cannot be found in the current environment or the connection password is incorrect. Enter the credentials again.</li></ol><div align="center"><img loading="lazy" height="364" width="1163" src="'+p+'" class="common_img" style="width:900px;"></div><ol start="6"><li>If the following prompt appears, it indicates that the module has successfully found and connected to the corresponding hotspot. The module will automatically restart and connect to the hotspot.</li></ol><div align="center"><img loading="lazy" height="269" width="640" src="'+u+'" class="common_img" style="width:500px;"></div><p>After the module completes network configuration, it must be bound to the platform agent. The screen displays the device ID and the binding URL while playing a voice broadcast of the verification code. Refer to the next section for detailed information to complete the device binding, noting that the <strong>XXXXXX</strong> at the end of the binding URL represents the device ID.</p><div align="center"><img loading="lazy" height="1872" width="1555" src="'+w+'" class="common_img" style="width:300px;"></div><p id="anther2.1.3"></p><h3 id="_2-1-3-device-binding" tabindex="-1">2.1.3 Device Binding <a class="header-anchor" href="#_2-1-3-device-binding" aria-label="Permalink to &quot;2.1.3 Device Binding&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>An account on the WonderHUB AI platform is required before binding the device. If an account does not exist, follow the steps below to register.</strong></p></div><p><strong>1. WonderHUB AI Account Registration</strong></p><ol><li>Open any browser and enter the following URL: <strong>hiwonder.ai</strong>. Alternatively, click the <a href="https://hiwonder.ai/" target="_blank" rel="noreferrer"><u>WonderHUB AI Chatbot</u></a> hyperlink for direct access.</li></ol><div align="center"><img loading="lazy" height="1040" width="1920" src="'+b+'" class="common_img" style="width:1000px;"></div><ol start="2"><li>To register a WonderHUB AI account, click <strong>Register</strong> in the bottom right corner.</li></ol><div align="center"><img loading="lazy" height="578" width="412" src="'+f+'" class="common_img" style="width:300px;"></div><ol start="3"><li>Fill in the required information and click <strong>Send Verification Code</strong> to obtain the registration verification code, then register the account.</li></ol><div align="center"><img loading="lazy" height="653" width="412" src="'+_+'" class="common_img" style="width:300px;"></div><ol start="4"><li>Check the box to agree to the user agreement and privacy policy, and then click <strong>Register</strong> to complete the registration.</li></ol><div align="center"><img loading="lazy" height="730" width="408" src="'+k+'" class="common_img" style="width:300px;"></div><ol start="5"><li>After logging into the newly registered account, a beginner&#39;s guide will appear. Follow this guide to quickly become familiar with the WonderHUB AI platform.</li></ol><div align="center"><img loading="lazy" height="921" width="1920" src="'+v+'" class="common_img" style="width:1500px;"></div><p><strong>2. Quick Binding</strong></p><ol><li>Click <strong>Agents</strong> on the left menu to switch to the agents interface.</li></ol><div align="center"><img loading="lazy" height="919" width="1920" src="'+y+'" class="common_img" style="width:1500px;"></div><ol start="2"><li>Click <strong>Manage Devices</strong> under the default agent <strong>General Assistant</strong>.</li></ol><div align="center"><img loading="lazy" height="919" width="1920" src="'+D+'" class="common_img" style="width:1500px;"></div><ol start="3"><li>Enter the <strong>6-digit device code</strong> displayed on the module screen into the input field for the device binding code, and click <strong>Add Device</strong> to complete the binding.</li></ol><div align="center"><img loading="lazy" height="918" width="1920" src="'+x+'" class="common_img" style="width:1500px;"></div><ol start="4"><li>If a white circular loading bar appears on the module screen after binding, it indicates that the module is connecting to the network using the stored Wi-Fi credentials. If the network connection fails, the screen will display the device hotspot name and the access URL, accompanied by a voice broadcast. In this case, follow the instructions in <a href="#anther2.1.2">Section 2.1.2 Module Network Configuration</a> to reconfigure the Wi-Fi settings for the current environment.</li></ol><div align="center"><img loading="lazy" height="723" width="650" src="'+I+'" class="common_img" style="width:300px;"></div><ol start="5"><li>If the white circular loading bar finishes loading and the screen successfully switches to the module expression interface, it indicates that all configurations are correct. The module is ready to start human-robot interaction.</li></ol><div align="center"><img loading="lazy" height="725" width="627" src="'+A+'" class="common_img" style="width:300px;"></div><p id="anther2.1.4"></p><h3 id="_2-1-4-smart-chat" tabindex="-1">2.1.4 Smart Chat <a class="header-anchor" href="#_2-1-4-smart-chat" aria-label="Permalink to &quot;2.1.4 Smart Chat&quot;">​</a></h3><p>After completing the preparation steps, awaken the module to enter chat mode by saying the wake word <strong>Hello Hiwonder</strong> or briefly pressing the <strong>right button</strong>.</p><p>The module features built-in special functions that can be triggered through spoken commands during human-robot interaction. Refer to the following command examples to query all currently supported special functions of the WonderLLM module: <strong>① How can you help me?</strong> or <strong>② Could you give me an overview of your capabilities?</strong></p><p>Refer to the following command examples to trigger specific functions of the WonderLLM module:</p><ol><li>Weather query function: <strong>Check the weather in [Region].</strong></li></ol><div align="center"><img loading="lazy" height="601" width="540" src="'+P+'" class="common_img" style="width:400px;"></div><ol start="2"><li>News broadcast function: <strong>① Broadcast today&#39;s news.</strong> or <strong>② Introduce today&#39;s trending events.</strong></li></ol><div align="center"><img loading="lazy" height="602" width="540" src="'+q+'" class="common_img" style="width:400px;"></div><ol start="3"><li>Outfit suggestions function: <strong>Suggest outfit combinations for going out today.</strong></li></ol><div align="center"><img loading="lazy" height="613" width="551" src="'+j+'" class="common_img" style="width:400px;"></div><ol start="4"><li>Joke-telling function: <strong>① Tell a joke.</strong> or <strong>② Share a funny joke.</strong></li></ol><div align="center"><img loading="lazy" height="612" width="551" src="'+C+'" class="common_img" style="width:400px;"></div><ol start="5"><li>Music playback function: <strong>Play some music on shuffle.</strong></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>It is recommended to lower the volume of the module when using the music playback function.</strong></p></div><div align="center"><img loading="lazy" height="713" width="626" src="'+S+'" class="common_img" style="width:350px;"></div><h2 id="_2-2-hardware-preparation" tabindex="-1">2.2 Hardware Preparation <a class="header-anchor" href="#_2-2-hardware-preparation" aria-label="Permalink to &quot;2.2 Hardware Preparation&quot;">​</a></h2><h3 id="_2-2-1-powering-on" tabindex="-1">2.2.1 Powering On <a class="header-anchor" href="#_2-2-1-powering-on" aria-label="Permalink to &quot;2.2.1 Powering On&quot;">​</a></h3><ol><li>Insert the battery into the slot at the bottom of the controller.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Do not reverse the positive and negative poles.</strong></p></div><div align="center"><img loading="lazy" height="1200" width="1200" src="'+z+'" class="common_img" style="width:300px;"></div><ol start="2"><li>Turn on the power switch. The power indicator LED on the controller lights red, indicating a successful power-on.</li></ol><div align="center"><img loading="lazy" height="656" width="486" src="'+T+'" class="common_img" style="width:300px;"></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When powering on for the first time, follow the steps in <a href="#p2-2-2">Section 2.2.2 Charging</a> to charge the controller for about 5 seconds to activate the built-in battery protection chip. Once activated, reactivation is not required unless the battery is unplugged.</strong></p></div><p id="p2-2-2"></p><h3 id="_2-2-2-charging" tabindex="-1">2.2.2 Charging <a class="header-anchor" href="#_2-2-2-charging" aria-label="Permalink to &quot;2.2.2 Charging&quot;">​</a></h3><ol><li>Ensure that the power switch of the controller is toggled to <strong>OFF</strong>. Connect one end of the USB cable to the charging port of the controller, and the other end to the charger.</li></ol><div align="center"><img loading="lazy" height="1146" width="860" src="'+O+'" class="common_img" style="width:400px;"></div><ol start="2"><li>The indicator LED on the controller lights up in blue during charging and turns off when fully charged. Unplug the power cable promptly after charging is complete to avoid overcharging.</li></ol><div align="center"><img loading="lazy" height="2961" width="3214" src="'+B+'" class="common_img" style="width:400px;"></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The power switch must be turned off during charging. Otherwise, the battery cannot be fully charged. Unplug the charger and the power source promptly after charging is complete to prevent overcharging from damaging the battery. Do not leave the charging process unattended.</strong></p></div><h2 id="_2-3-software-configuration" tabindex="-1">2.3 Software Configuration <a class="header-anchor" href="#_2-3-software-configuration" aria-label="Permalink to &quot;2.3 Software Configuration&quot;">​</a></h2><h3 id="_2-3-1-installing-wondercode-programming-software" tabindex="-1">2.3.1 Installing WonderCode Programming Software <a class="header-anchor" href="#_2-3-1-installing-wondercode-programming-software" aria-label="Permalink to &quot;2.3.1 Installing WonderCode Programming Software&quot;">​</a></h3><ol><li>Open the <a href="https://www.hiwonder.net/pc-programming-software" target="_blank" rel="noreferrer">WonderCode setup.exe</a> software installation package.</li></ol><div align="center"><img loading="lazy" height="105" width="75" src="'+L+'" class="common_img" style="width:100px;border:1px solid black;"></div><ol start="2"><li>Select the language, and then click <strong>OK</strong>.</li></ol><div align="center"><img loading="lazy" height="162" width="349" src="'+E+'" class="common_img" style="width:400px;border:1px solid black;"></div><ol start="3"><li>Select the installation directory, and then click <strong>Next</strong>.</li></ol><div align="center"><img loading="lazy" height="415" width="582" src="'+M+'" class="common_img" style="width:500px;border:1px solid black;"></div><ol start="4"><li>Click <strong>Next</strong>.</li></ol><div align="center"><img loading="lazy" height="415" width="582" src="'+R+'" class="common_img" style="width:500px;border:1px solid black;"></div><ol start="5"><li>Click <strong>Install</strong>.</li></ol><div align="center"><img loading="lazy" height="415" width="582" src="'+H+'" class="common_img" style="width:500px;border:1px solid black;"></div><div align="center"><img loading="lazy" height="415" width="582" src="'+N+'" class="common_img" style="width:500px;border:1px solid black;"></div><ol start="6"><li>After a successful installation, click <strong>Finish</strong>.</li></ol><div align="center"><img loading="lazy" height="415" width="582" src="'+U+'" class="common_img" style="width:500px;border:1px solid black;"></div><h2 id="_2-4-starter-project-1-blinking-onboard-rgb-lights" tabindex="-1">2.4 Starter Project 1: Blinking Onboard RGB Lights <a class="header-anchor" href="#_2-4-starter-project-1-blinking-onboard-rgb-lights" aria-label="Permalink to &quot;2.4 Starter Project 1: Blinking Onboard RGB Lights&quot;">​</a></h2><h3 id="_2-4-1-programming" tabindex="-1">2.4.1 Programming <a class="header-anchor" href="#_2-4-1-programming" aria-label="Permalink to &quot;2.4.1 Programming&quot;">​</a></h3><ol><li>Create a file: Open the programming software, and click <strong>File</strong> -&gt; <strong>New</strong>.</li></ol><div align="center"><img loading="lazy" height="893" width="1386" src="'+W+'" class="common_img" style="width:800px;"></div><ol start="2"><li>Add extensions:</li></ol><ul><li>Click the extensions icon in the bottom left corner.</li></ul><div align="center"><img loading="lazy" height="893" width="1386" src="'+F+'" class="common_img" style="width:800px;"></div><ul><li>In the <strong>Choose an Extension</strong> menu, select <strong>Controller</strong> and then add <strong>K12 ESP32</strong>.</li></ul><div align="center"><img loading="lazy" height="893" width="1386" src="'+Q+'" class="common_img" style="width:800px;"></div><ul><li>Once successfully added, the added extension package is visible on the WonderCode interface.</li></ul><div align="center"><img loading="lazy" height="893" width="1386" src="'+X+'" class="common_img" style="width:800px;"></div><ol start="3"><li>Write the program: Drag the corresponding blocks from the block palette to the scripting area for programming. Once completed, the translated Python code is visible in the code display and upload area.</li></ol><div align="center"><img loading="lazy" height="326" width="351" src="'+J+'" class="common_img" style="width:400px;"></div><p>The source files are available for download as a zip archive under <a href="https://drive.google.com/drive/folders/1C_cT51H9adfUnSPw9l57vPrQQ2A_vUBa?usp=sharing" target="_blank" rel="noreferrer">1. Source Code / 03 Program Files for Starter Projects</a>.</p><h3 id="_2-4-2-downloading-the-program" tabindex="-1">2.4.2 Downloading the Program <a class="header-anchor" href="#_2-4-2-downloading-the-program" aria-label="Permalink to &quot;2.4.2 Downloading the Program&quot;">​</a></h3><div align="center"><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The connection port number is not unique. The port connected in this section is &quot;COM3&quot;. Do not connect to &quot;COM1&quot;, which is typically used for system communication. If multiple COM ports are displayed and the correct one cannot be determined, right-click &quot;This PC&quot; on the computer, select &quot;Properties&quot;, and then click &quot;Device Manager&quot; to find the port number corresponding to the controller. The port labeled with &quot;CH340&quot; is the correct one.</strong></p></div><div align="center"><img loading="lazy" height="129" width="240" src="'+V+'" class="common_img" style="width:400px;"></div><h3 id="_2-4-3-program-outcome" tabindex="-1">2.4.3 Program Outcome <a class="header-anchor" href="#_2-4-3-program-outcome" aria-label="Permalink to &quot;2.4.3 Program Outcome&quot;">​</a></h3><p>Once the program starts running, the two onboard RGB LEDs of the controller switch colors every second in the order of red, green, and blue.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The following starter projects introduce the electronic modules used in this kit for a quick start. For a detailed description of the modules, refer to <a href="https://wiki.hiwonder.com/projects/DaDablock-AI/en/starter-kit/docs/4_Software_and_Hardware_Guide.html#electronic-modules-overview" target="_blank" rel="noreferrer">Section 4.3 Electronic Module Overview</a> for detailed information.</strong></p></div><h2 id="_2-5-starter-project-2-dual-servos-and-dot-matrix-display" tabindex="-1">2.5 Starter Project 2: Dual Servos and Dot Matrix Display <a class="header-anchor" href="#_2-5-starter-project-2-dual-servos-and-dot-matrix-display" aria-label="Permalink to &quot;2.5 Starter Project 2: Dual Servos and Dot Matrix Display&quot;">​</a></h2><h3 id="_2-5-1-learning-objectives" tabindex="-1">2.5.1 Learning Objectives <a class="header-anchor" href="#_2-5-1-learning-objectives" aria-label="Permalink to &quot;2.5.1 Learning Objectives&quot;">​</a></h3><ol><li>Familiar with the dot matrix module and master the basic usage of displaying preset expression patterns.</li><li>Master the method of adjusting the angle of the 270° servo controlled by the ESP32 controller, and understand the logic of using variables to control servo motion.</li><li>Master the method of adjusting the speed and direction of the DC motor controlled by the ESP32 controller, and understand the control logic of forward rotation, reverse rotation, and stopping.</li></ol><h3 id="_2-5-2-wiring-diagram" tabindex="-1">2.5.2 Wiring Diagram <a class="header-anchor" href="#_2-5-2-wiring-diagram" aria-label="Permalink to &quot;2.5.2 Wiring Diagram&quot;">​</a></h3><ol><li><p>Connect the dot matrix module cable to port 5 of the ESP32 controller.</p></li><li><p>Connect the 270° block servo cable to port S1 of the ESP32 controller, inserting the orange wire into the white pin of port S1.</p></li><li><p>Connect the 360° block motor cable to port S2 of the ESP32 controller, inserting the orange wire into the white pin of port S2.</p></li></ol><p>As shown in the diagram:</p><div align="center"><img loading="lazy" height="487" width="560" src="'+G+'" class="common_img" style="width:400px;"></div><h3 id="_2-5-3-programming" tabindex="-1">2.5.3 Programming <a class="header-anchor" href="#_2-5-3-programming" aria-label="Permalink to &quot;2.5.3 Programming&quot;">​</a></h3><h4 id="_2-add-extension-libraries" tabindex="-1">(2) Add Extension Libraries <a class="header-anchor" href="#_2-add-extension-libraries" aria-label="Permalink to &quot;(2) Add Extension Libraries&quot;">​</a></h4><p>In the <strong>Choose an Extension</strong> menu, select <strong>Output modules</strong> and add the <strong>Dot matrix module</strong>.</p><div align="center"><img loading="lazy" height="893" width="1386" src="'+i+'" class="common_img" style="width:800px;"></div><h4 id="_4-complete-program" tabindex="-1">(4) Complete Program <a class="header-anchor" href="#_4-complete-program" aria-label="Permalink to &quot;(4) Complete Program&quot;">​</a></h4><div align="center"><img loading="lazy" height="763" width="667" src="'+K+'" class="common_img" style="width:500px;"></div><p>The source files are available for download as a zip archive under <a href="https://drive.google.com/drive/folders/1C_cT51H9adfUnSPw9l57vPrQQ2A_vUBa?usp=sharing" target="_blank" rel="noreferrer">1. Source Code / 03 Program Files for Starter Projects</a>.</p><h3 id="_2-5-4-downloading-the-program" tabindex="-1">2.5.4 Downloading the Program <a class="header-anchor" href="#_2-5-4-downloading-the-program" aria-label="Permalink to &quot;2.5.4 Downloading the Program&quot;">​</a></h3><div align="center"><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"></div><h3 id="_2-5-5-program-outcome" tabindex="-1">2.5.5 Program Outcome <a class="header-anchor" href="#_2-5-5-program-outcome" aria-label="Permalink to &quot;2.5.5 Program Outcome&quot;">​</a></h3><p>Once the program starts running, initialize the dot matrix screen port and set the brightness. Rotate the 270° block servo connected to port <strong>S1</strong> to 135°. Then, execute the loop. First, the dot matrix screen displays pattern <strong>S1</strong> and waits for 2 seconds. The servo at <strong>S1</strong> then rotates to 270° and 0° sequentially, waiting for 2 seconds after each rotation. Next, the dot matrix screen displays pattern <strong>S2</strong> and waits for 2 seconds. The 360° block motor connected to port <strong>S2</strong> then rotates at speed 50, and the dot matrix screen displays the text <strong>ON</strong>. After waiting for 5 seconds, the motor at <strong>S2</strong> stops, and the dot matrix screen displays the number 0.</p>',138)])])}const lt=a(Z,[["render",$]]);export{st as __pageData,lt as default};
